"""The brand mark: the 20 x 6 anvil of design/system/logo.md, read from `anvil.json` (generated by design/system/build_mark.py from
the approved art; never edited by hand). Every glyph is plain ASCII, so the same art serves every glyph set.

A terminal with true colour or 256 colours and the dark theme draws each cell in the art's own colour (at 256, the nearest entry), a
soft pink gradient the palette roles cannot hold. Everywhere else (the light theme, 16 colours) each cell is drawn in the role the
file names for it, so contrast holds on any ground; with colour off it is the plain glyphs.
"""
import json
import os

from forge.ui.model import Span

with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "anvil.json"), encoding="utf-8") as _f:
    ART = json.load(_f)
HEIGHT, WIDTH = ART["height"], ART["width"]


def mark_lines(ctx):
    """The mark as HEIGHT lists of spans for header(): runs of cells that share a colour (or a role) are one span."""
    exact = ctx.color in ("truecolor", "256") and ctx.theme == "dark"
    out = []
    for glyphs, colors, letters in zip(ART["rows"], ART["colors"], ART["roles"]):
        spans, key = [], None
        for g, c, r in zip(glyphs, colors, letters):
            cell = ("body", None) if g == " " else (ART["role_letters"][r], c if exact else None)
            if cell == key:
                spans[-1].text += g
            else:
                spans.append(Span(cell[0], g, rgb=cell[1]))
                key = cell
        out.append(spans)
    return out
